// ai-agents/checks/src/independent-approval.ts  (the reusable workflow runs node /app/dist/independent-approval.js in the ai-agents-checks image)
// Pass only when someone other than the requester approved the PR's latest commit.
export interface Pr { user: { login: string }; body: string | null }
export interface Review { state: string; commit_id: string; user: { login: string; type: string } }

const AGENT_BOTS = new Set(["rhino-ai-agents[bot]"]);
const REQUESTED_BY = /^Requested-by:\s*@?([A-Za-z0-9-]+)\s*$/m;
const DECISIVE = new Set(["APPROVED", "CHANGES_REQUESTED", "DISMISSED"]); // a later plain comment doesn't undo an approval

export class MissingRequester extends Error {}

export function requesters(pr: Pr, commitAuthors: string[], bodyEditors: string[]): Set<string> {
  const people = [pr.user.login];
  if (AGENT_BOTS.has(pr.user.login)) {
    const found = REQUESTED_BY.exec(pr.body ?? "")?.[1];
    if (!found) throw new MissingRequester("Agent PR without a 'Requested-by:' line. The orchestrator writes it; failing closed.");
    people.push(found);
  }
  // Anyone who pushed code or rewrote the PR body is part of the change, so they can't approve it.
  return new Set([...people, ...commitAuthors, ...bodyEditors].map((p) => p.toLowerCase()));
}

export function independentApprovers(reviews: Review[], headSha: string, people: Set<string>): Set<string> {
  const latest = new Map<string, Review>();
  for (const review of reviews) { // the API lists oldest first; keep each reviewer's last decisive review
    if (DECISIVE.has(review.state)) latest.set(review.user.login.toLowerCase(), review);
  }
  return new Set([...latest].filter(([login, review]) =>
    review.state === "APPROVED"
    && review.commit_id === headSha
    && review.user.type === "User" // approvals from apps never count
    && !people.has(login)).map(([login]) => login));
}
// main(): Octokit reads the PR, its commits, body edits and reviews; no independent approver sets process.exitCode = 1.

// ai-agents/gateway/src/server.ts  (image ai-agents-llm-gateway: node:24-bookworm-slim, CMD ["node", "dist/server.js"])
import { createServer } from "node:http";
import { Readable, Transform } from "node:stream";
import { buffer } from "node:stream/consumers";
import { pipeline } from "node:stream/promises";
import { Agent } from "undici"; // 7.x, the engine inside Node 24's fetch; used only for the waits below
import { RunTokenError, verifyRunToken } from "./auth.js"; // HMAC token from the orchestrator: agent, jira, run, exp, epoch
import { workloadKey } from "./keys.js"; // Anthropic key per workload, from the ExternalSecret mount
import { Meter } from "./meter.js"; // usage counting (next ticket)

const ROUTES = new Set(["/v1/messages", "/v1/messages/count_tokens"]);
const FORWARD = ["anthropic-version", "anthropic-beta", "content-type", "accept"];
const RETURN = ["content-type", "request-id", "retry-after", "anthropic-ratelimit-requests-remaining"];
const upstream = new Agent({ connect: { timeout: 10_000 }, headersTimeout: 900_000, bodyTimeout: 900_000 }); // per wait, never a total

// Never refuses over budget: 429 and 529 pass through with retry-after, and the harness retries.
createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", "http://gateway");
  if (req.method === "GET" && url.pathname === "/health") return void res.end("ok");
  if (req.method !== "POST" || !ROUTES.has(url.pathname)) return void res.writeHead(404).end();
  try {
    const claims = verifyRunToken(req.headers.authorization ?? ""); // RunTokenError if missing, expired or revoked
    const headers = Object.fromEntries(FORWARD.flatMap((h) => (req.headers[h] ? [[h, String(req.headers[h])]] : [])));
    const up = await fetch(`https://api.anthropic.com${url.pathname}${url.search}`, {
      method: "POST", body: await buffer(req), dispatcher: upstream, // no 1 MiB cap here: Anthropic caps request size itself
      headers: { ...headers, "x-api-key": workloadKey(claims.agent), "accept-encoding": "identity" }, // VM never sees the key
    });
    res.writeHead(up.status, Object.fromEntries(RETURN.flatMap((h) => { const v = up.headers.get(h); return v ? [[h, v]] : []; })));
    const meter = new Meter(claims, String(req.headers["x-ai-agents-step"] ?? "unknown"));
    const tap = new Transform({ transform(chunk: Buffer, _enc, done) { meter.feed(chunk); done(null, chunk); } }); // usage only
    await pipeline(up.body ? Readable.fromWeb(up.body) : Readable.from([]), tap, res).finally(() => { meter.close(); });
  } catch (error) {
    if (!res.headersSent) res.writeHead(error instanceof RunTokenError ? 401 : 502).end();
  }
}).listen(8080); // access log (method, path, status, latency) only; no body is ever logged

// ai-agents/gateway/src/meter.ts
import { createServer } from "node:http";
import { Counter, register } from "@prometheus-io/client"; // prom-client's new name (same API)
import type { RunClaims } from "./auth.js";
import { pricePerMtok } from "./prices.js"; // gateway/prices.yaml: $ per million tokens by model and token type
const TOKENS = new Counter({ name: "ai_agents_llm_tokens_total", help: "Tokens through the gateway", labelNames: ["agent", "model", "type", "step"] });
const COST = new Counter({ name: "ai_agents_llm_cost_usd_total", help: "Estimated cost in USD", labelNames: ["agent", "model", "jira", "run", "step"] });
type Usage = { model?: string; usage?: Record<string, unknown>; message?: Usage };
export class Meter { // reads only the usage numbers of a Messages response; text is never kept or logged
  #model = "unknown"; #usage: Record<string, number> = {}; #buf = ""; #utf8 = new TextDecoder();
  constructor(readonly claims: RunClaims, readonly step: string) {}
  feed(chunk: Buffer): void {
    const events = (this.#buf + this.#utf8.decode(chunk, { stream: true })).split("\n\n"); // an SSE event ends with a blank line
    this.#buf = events.pop() ?? "";
    for (const line of events.flatMap((event) => event.split("\n"))) {
      if (line.startsWith("data: ") && line.includes('"usage"')) this.#take(JSON.parse(line.slice(6)) as Usage);
    }
  }
  #take(data: Usage): void {
    const msg = data.message ?? data; // message_start nests it; message_delta and plain JSON don't
    this.#model = msg.model ?? this.#model;
    const usage = msg.usage ?? {};
    for (const [k, v] of Object.entries(usage)) if (Number.isInteger(v)) this.#usage[k] = v as number;
    const hour = (usage.cache_creation as { ephemeral_1h_input_tokens?: number } | undefined)?.ephemeral_1h_input_tokens;
    if (Number.isInteger(hour)) this.#usage.cache_write_1h = hour as number; // 1-hour writes cost more than 5-minute ones
  }
  close(): void {
    if (this.#buf.trim().startsWith("{")) this.#take(JSON.parse(this.#buf) as Usage); // a non-streaming call: one JSON object
    const u = this.#usage, { agent, jira, run } = this.claims, labels = { agent, model: this.#model, step: this.step };
    const hour = u.cache_write_1h ?? 0, writes = u.cache_creation_input_tokens ?? 0;
    const parts = { input: u.input_tokens ?? 0, output: u.output_tokens ?? 0, cache_write_5m: writes - hour,
      cache_write_1h: hour, cache_read: u.cache_read_input_tokens ?? 0 };
    for (const [type, n] of Object.entries(parts)) TOKENS.inc({ ...labels, type: type.replace(/_(5m|1h)$/, "") }, n); // G1 reads type="cache_write"
    const cost = Object.entries(parts).reduce((sum, [type, n]) => sum + n * pricePerMtok(this.#model, type), 0) / 1_000_000;
    COST.inc({ ...labels, jira, run }, cost);
  }
}
createServer(async (_req, res) => res.writeHead(200, { "Content-Type": register.contentType }).end(await register.metrics()))
  .listen(9090); // Prometheus metrics on :9090, apart from the API on :8080

# infrastructure/multi_tenant/accounts/infrastructure/ai-agents/llm-gateway/terragrunt.hcl
include "root" {
  path   = find_in_parent_folders("root.hcl")
  expose = true
}

terraform {
  # New module (this ticket): a local chart shaped like modules/goalert/chart; G3's services reuse it.
  source = "../../../../../modules/ai-agents-service//"
}

inputs = {
  name         = "llm-gateway"
  namespace    = "ai-agents"
  image        = "123456789012.dkr.ecr.us-east-1.amazonaws.com/ai-agents-llm-gateway:0.1.0" # CMD: node dist/server.js
  replicas     = 2
  port         = 8080
  metrics_port = 9090
  health_path  = "/health" # readiness and liveness; user 10001, read-only root filesystem

  # ExternalSecrets through the existing ClusterSecretStore vault-store
  vault_secret_paths = ["infrastructure/ai-agents/anthropic", "infrastructure/ai-agents/gateway"]

  env = {
    SPEND_QUERY_URL = "http://vmselect-rhino-metrics.${include.root.locals.metrics_namespace}:8481/select/0/prometheus"
  }

  route = {
    parent_ref      = "envoy-internal" # VPN, Teleport and in-cluster callers only in v0
    hostname        = "llm-gateway.example.com"
    request_timeout = "0s"             # no route timeout: streams with 64K-128K output run for many minutes
  }
  # Decide with G3: how sandbox VMs in the ai-agents account reach this without VPC peering
  # (a PrivateLink endpoint service, or envoy-external + WAF behind the egress proxy).
}

// ai-agents/checks/src/locked-checks.ts  (fcp calls it like independent-approval.ts)
// Fail an agent PR that changes the checks it is judged by. Human PRs are not limited here.
import { matchesGlob } from "node:path";
import { isDeepStrictEqual } from "node:util";
import { parse } from "smol-toml"; // a small TOML parser: compare parsed sections, not text

const AGENT_BOTS = new Set(["rhino-ai-agents[bot]"]);
const LOCKED = [ // fcp's block of settings/protected-paths.yaml (G3-21's hooks read it too), inline here to read
  ".github/**", // workflows, scripts, the PR template
  ".claude/settings.json", "scripts/claude_stop_verify.sh", "scripts/poe_verify.py", "frontend/scripts/verify.ts", // verify (G7)
  ".flake8", ".pre-commit-config.yaml",
  "frontend/biome.json", "frontend/tsconfig.json", "frontend/vitest.config.js",
  "frontend/playwright.config.ts", "frontend/stryker.config.mjs",
  "cloud/.coveragerc", "client/rhinoOnPrem/.coveragerc", "sdk/.coveragerc", "sdk/tox.ini",
];
const LOCKED_TOOL_SECTIONS = ["black", "isort", "flake8", "coverage", "pytest"];
const PLAN_BLOCK = /<!-- ai-agents:locked-checks\n([\s\S]*?)\n-->/; // written by the orchestrator (G4)

type ReadFile = (path: string, sha: string) => Promise<string>; // file content at a commit, through Octokit
interface Pr { user: { login: string }; body: string | null; base: { sha: string }; head: { sha: string } }

export async function violations(pr: Pr, files: string[], readFile: ReadFile): Promise<string[]> {
  if (!AGENT_BOTS.has(pr.user.login)) return [];
  const block = PLAN_BLOCK.exec(pr.body ?? "")?.[1];
  const locked = [...LOCKED, ...(block?.split(/\s+/).filter(Boolean) ?? [])];
  const bad = files.filter((f) => locked.some((pattern) => matchesGlob(f, pattern)));
  if (files.includes("pyproject.toml")) { // dependencies may change; lint and test settings may not
    const tool = async (sha: string) => (parse(await readFile("pyproject.toml", sha)).tool ?? {}) as Record<string, unknown>;
    const [base, head] = await Promise.all([tool(pr.base.sha), tool(pr.head.sha)]);
    bad.push(...LOCKED_TOOL_SECTIONS.filter((s) => !isDeepStrictEqual(base[s], head[s])).map((s) => `pyproject.toml [tool.${s}]`));
  }
  return bad; // non-empty: the job fails and lists each file; a person can take the PR over
}

// ai-agents/checks/src/weakened-tests.ts
// Call out test edits that make tests easier to pass. Annotations only: editing tests is allowed.
const TEST_PATH = /(^|\/)(tests?|e2e|integration-tests)\/|\.(test|spec)\.tsx?$|(^|\/)test_[^/]+\.py$/;
const ASSERTION = /\bexpect\(|\bassert\b|self\.assert\w+\(|pytest\.raises\(|toThrow|toHaveBeenCalled/;
const SKIP_OR_FOCUS =
  /\b(it|test|describe)\.(skip|todo|fixme|only)\(|\bx(it|describe)\(|@pytest\.mark\.(skip|xfail)|@unittest\.skip/;
const THRESHOLD = /(fail[_-]under|thresholds?|retries|timeout)\W+([\d.]+)/i;

export type Finding = [kind: string, text: string];

export function findings(path: string, patch: string): Finding[] {
  const out: Finding[] = [];
  let removed = 0;
  let added = 0;
  for (const line of patch.split("\n")) {
    const [sign, text] = [line.slice(0, 1), line.slice(1)];
    if ((sign !== "+" && sign !== "-") || line.startsWith("+++") || line.startsWith("---")) continue;
    if (TEST_PATH.test(path) && ASSERTION.test(text)) {
      if (sign === "-") removed += 1;
      else added += 1;
    }
    if (sign === "+" && SKIP_OR_FOCUS.test(text)) out.push(["new skip or focus", text.trim()]);
    if (sign === "-" && THRESHOLD.test(text)) out.push(["threshold changed: check it was not loosened", text.trim()]);
  }
  if (removed > added) out.push(["assertions removed", `${removed - added} more assertions removed than added`]);
  return out; // printed as ::warning file=<path>:: lines plus a job summary
}
